let allEvents = [];

// Loop through all items coming from the LLM Chain
for (const item of $input.all()) {
  try {
    // 1. Get the text and clean off the markdown tags
    const cleanText = item.json.text.replace(
      /```json|```/g, '').trim();

    // 2. Parse the string into actual JSON
    const parsedEvents = JSON.parse(cleanText);

    // 3. If it is a valid array of events (and not empty []), add them to our master list
    if (Array.isArray(parsedEvents) && parsedEvents.length > 0) {
      allEvents = allEvents.concat(parsedEvents);
    }
  } catch (error) {
    // If the LLM spits out bad formatting that breaks JSON.parse, just skip it and keep going
    continue;
  }
}

// Return the final combined list of real events
return allEvents;

// Get new events from AI extraction
const newEvents = $('🔧 Clean & Combine All Extracted Events').all();

// Get existing events from the Google Sheet
const existingEvents = $('📋 Read Existing Events from Edinburgh DB').all();

// Build a set of existing event keys (Name + Date combo) for fast lookup
const existingKeys = new Set(
  existingEvents.map(row => {
    const name = (row.json['Event Name'] || '').toLowerCase().trim();
    const date = (row.json['Date'] || '').toLowerCase().trim();
    return `${name}|${date}`;
  })
);

// Filter to only truly new events not already in the sheet
const uniqueNewEvents = newEvents.filter(event => {
  const name = (event.json['Event Name'] || '').toLowerCase().trim();
  const date = (event.json['Date'] || '').toLowerCase().trim();
  const key = `${name}|${date}`;
  return !existingKeys.has(key) && name.length > 2;
});

if (uniqueNewEvents.length === 0) {
  // Return a sentinel item so downstream knows nothing new was found
  return [{json: {newEventsCount: 0, events: [], noNewEvents: true}}];
}

// Add a count field so the Telegram message can use it
return uniqueNewEvents.map(e => ({json: {...e.json, newEventsCount: uniqueNewEvents.length, noNewEvents: false}}));

// Aggregate all events into one Telegram summary message
const items = $input.all();
const count = items[0]?.json?.newEventsCount || items.length;

const eventList = items
  .map((item, i) => {
    const name = item.json['Event Name'] || 'Unknown Event';
    const date = item.json['Date'] || 'TBC';
    const venue = item.json['Venue'] || 'TBC';
    return `${i + 1}. *${name}*\n   📅 ${date} | 📍 ${venue}`;
  })
  .join('\n\n');

return [{
  json: {
    message: `🎪 *${count} New Edinburgh Event(s) Found!*\n\n${eventList}\n\n💡 Consider adjusting your Airbnb pricing or running a promotion for these dates. Check the full list in your events spreadsheet.`
  }
}];
